#!/usr/bin/env python3
"""Regenerate synthetic F36c jacket fixtures (requires CairoSVG and Pillow)."""
from io import BytesIO
from pathlib import Path
import cairosvg
from PIL import Image

root = Path(__file__).resolve().parent
lines = ['// SPDX-License-Identifier: GPL-3.0-or-later',
         '// Generated by generate_series_jackets.py from the approved synthetic SVG fixtures.',
         '#pragma once', '#include <array>', '#include <cstdint>',
         'namespace seriesSurfaceScenario {',
         'inline constexpr std::array<std::array<uint8_t, 3072>, 3> Jackets = {{']
for source in sorted((root / 'series-fixtures').glob('jacket-*.svg')):
    bitmap = cairosvg.svg2png(url=str(source), output_width=128, output_height=192, background_color='white')
    data = Image.open(BytesIO(bitmap)).convert('RGB').convert('1').tobytes()
    assert len(data) == 3072
    lines.append('  {{')
    for offset in range(0, len(data), 16):
        lines.append('    ' + ', '.join(f'0x{byte:02x}' for byte in data[offset:offset + 16]) + ',')
    lines.append('  }},')
lines += ['}};', '} // namespace seriesSurfaceScenario', '']
(root / 'SeriesJackets.h').write_text('\n'.join(lines))
